#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

class Solution {
public:
    std::vector<int> countMentions(int numberOfUsers, std::vector<std::vector<std::string>>& events) {
        std::sort(events.begin(), events.end(), [](const auto& a, const auto& b) {
            int t_a = std::stoi(a[1]);
            int t_b = std::stoi(b[1]);
            if (t_a != t_b) return t_a < t_b;
            int prio_a = (a[0] == "OFFLINE") ? 0 : 1;
            int prio_b = (b[0] == "OFFLINE") ? 0 : 1;
            return prio_a < prio_b;
        });

        std::vector<int> mentions(numberOfUsers, 0);
        std::vector<int> offline_until(numberOfUsers, 0);

        for (const auto& ev : events) {
            int curr_time = std::stoi(ev[1]);
            if (ev[0] == "OFFLINE") {
                int uid = std::stoi(ev[2]);
                offline_until[uid] = curr_time + 60;
            } else if (ev[0] == "MESSAGE") {
                if (ev[2] == "ALL") {
                    for (int i = 0; i < numberOfUsers; ++i) mentions[i]++;
                } else if (ev[2] == "HERE") {
                    for (int i = 0; i < numberOfUsers; ++i) {
                        if (curr_time >= offline_until[i]) mentions[i]++;
                    }
                } else {
                    std::stringstream ss(ev[2]);
                    std::string token;
                    while (ss >> token) {
                        int uid = std::stoi(token.substr(2));
                        mentions[uid]++;
                    }
                }
            }
        }
        return mentions;
    }
};

import java.util.*;

class Solution {
    public int[] countMentions(int numberOfUsers, List<List<String>> events) {
        events.sort((a, b) -> {
            int tA = Integer.parseInt(a.get(1));
            int tB = Integer.parseInt(b.get(1));
            if (tA != tB) return Integer.compare(tA, tB);
            int pA = a.get(0).equals("OFFLINE") ? 0 : 1;
            int pB = b.get(0).equals("OFFLINE") ? 0 : 1;
            return Integer.compare(pA, pB);
        });

        int[] mentions = new int[numberOfUsers];
        int[] offlineUntil = new int[numberOfUsers];

        for (List<String> ev : events) {
            int currTime = Integer.parseInt(ev.get(1));
            if (ev.get(0).equals("OFFLINE")) {
                int uid = Integer.parseInt(ev.get(2));
                offlineUntil[uid] = currTime + 60;
            } else {
                String data = ev.get(2);
                if (data.equals("ALL")) {
                    for (int i = 0; i < numberOfUsers; i++) mentions[i]++;
                } else if (data.equals("HERE")) {
                    for (int i = 0; i < numberOfUsers; i++) {
                        if (currTime >= offlineUntil[i]) mentions[i]++;
                    }
                } else {
                    String[] tokens = data.split(" ");
                    for (String token : tokens) {
                        int uid = Integer.parseInt(token.substring(2));
                        mentions[uid]++;
                    }
                }
            }
        }
        return mentions;
    }
}

var countMentions = function(numberOfUsers, events) {
    events.sort((a, b) => {
        const tA = Number(a[1]);
        const tB = Number(b[1]);
        if (tA !== tB) return tA - tB;
        const pA = a[0] === 'OFFLINE' ? 0 : 1;
        const pB = b[0] === 'OFFLINE' ? 0 : 1;
        return pA - pB;
    });

    const mentions = new Int32Array(numberOfUsers);
    const offlineUntil = new Int32Array(numberOfUsers);

    for (const [evType, tsStr, data] of events) {
        const currTime = Number(tsStr);
        if (evType === 'OFFLINE') {
            const uid = Number(data);
            offlineUntil[uid] = currTime + 60;
        } else {
            if (data === 'ALL') {
                for (let i = 0; i < numberOfUsers; i++) mentions[i]++;
            } else if (data === 'HERE') {
                for (let i = 0; i < numberOfUsers; i++) {
                    if (currTime >= offlineUntil[i]) mentions[i]++;
                }
            } else {
                const tokens = data.split(' ');
                for (const token of tokens) {
                    const uid = Number(token.slice(2));
                    mentions[uid]++;
                }
            }
        }
    }
    return Array.from(mentions);
};
